from pathlib import Path

path = Path('TimeRange.js')
text = path.read_text()

text = text.replace(
'''    #styleElement;\n    #syncing = 0;''',
'''    #styleElement;\n    #contourLayer;\n    #syncing = 0;''',
1
)

old = '''        const contourStyle =\n            document.createElement(\n                "style"\n            );\n\n        contourStyle.textContent = `\n            :host:not([overlapping]) {\n                background-image:\n                    radial-gradient(\n                        circle at center,\n                        rgba(0, 0, 0, 0.22)\n                            calc(50% - var(--time-range-ring-inset) - (var(--time-range-ring-width) / 2)),\n                        rgba(255, 255, 255, 0.30)\n                            calc(50% - var(--time-range-ring-inset)),\n                        rgba(0, 0, 0, 0.20)\n                            calc(50% - var(--time-range-ring-inset) + (var(--time-range-ring-width) / 2))\n                    ) !important;\n            }\n\n            :host([overlapping]) {\n                background-image: none !important;\n            }\n        `;\n\n        this.#styleElement =\n            document.createElement(\n                "style"\n            );\n\n        this.#shadowRoot.append(\n            contourStyle,\n            this.#styleElement\n        );'''

new = '''        const contourStyle =\n            document.createElement(\n                "style"\n            );\n\n        contourStyle.textContent = `\n            :host {\n                position: relative;\n            }\n\n            #contour {\n                position: absolute;\n                inset: 0;\n                pointer-events: none;\n                background-repeat: no-repeat;\n            }\n\n            :host([overlapping]) #contour {\n                display: none;\n            }\n        `;\n\n        this.#contourLayer =\n            document.createElement(\n                "div"\n            );\n\n        this.#contourLayer.id =\n            "contour";\n\n        this.#styleElement =\n            document.createElement(\n                "style"\n            );\n\n        this.#shadowRoot.append(\n            contourStyle,\n            this.#styleElement,\n            this.#contourLayer\n        );'''

if old not in text:
    raise SystemExit('constructor contour block not found')
text = text.replace(old, new, 1)

marker = '''    #updateClipPath() {\n        const parent =\n            this.parentElement;'''

helpers = '''    #getRingInnerMargin(\n        ring\n    ) {\n        if (\n            ring.hasAttribute(\n                "inner-margin"\n            )\n        ) {\n            return (\n                ring.getAttribute(\n                    "inner-margin"\n                ) ??\n                "0px"\n            );\n        }\n\n        return (\n            ring.getAttribute(\n                "margin"\n            ) ??\n            "0px"\n        );\n    }\n\n    #getRingOuterMargin(\n        ring\n    ) {\n        if (\n            ring.hasAttribute(\n                "outer-margin"\n            )\n        ) {\n            return (\n                ring.getAttribute(\n                    "outer-margin"\n                ) ??\n                "0px"\n            );\n        }\n\n        return (\n            ring.getAttribute(\n                "margin"\n            ) ??\n            "0px"\n        );\n    }\n\n    #collapseRingMargins(\n        first,\n        second\n    ) {\n        return `calc(max(0px, ${first}, ${second}) + min(0px, ${first}, ${second}))`;\n    }\n\n    #getPreviousRingContainer(\n        ring\n    ) {\n        let sibling =\n            ring.previousElementSibling;\n\n        while (sibling) {\n            if (\n                sibling.localName ===\n                    "ring-container"\n            ) {\n                return sibling;\n            }\n\n            sibling =\n                sibling.previousElementSibling;\n        }\n\n        return null;\n    }\n\n    #getEffectiveRingInset(\n        ring\n    ) {\n        const inset =\n            ring.getAttribute(\n                "inset"\n            );\n\n        if (\n            inset !== null &&\n            inset.trim().toLowerCase() !==\n                "auto"\n        ) {\n            return inset;\n        }\n\n        const width =\n            ring.getAttribute(\n                "width"\n            ) ??\n            "0px";\n\n        const previous =\n            this.#getPreviousRingContainer(\n                ring\n            );\n\n        if (!previous) {\n            return `calc(${this.#getRingOuterMargin(ring)} + (${width} / 2))`;\n        }\n\n        const previousInset =\n            this.#getEffectiveRingInset(\n                previous\n            );\n\n        const previousWidth =\n            previous.getAttribute(\n                "width"\n            ) ??\n            "0px";\n\n        const adjoiningMargin =\n            this.#collapseRingMargins(\n                this.#getRingInnerMargin(\n                    previous\n                ),\n                this.#getRingOuterMargin(\n                    ring\n                )\n            );\n\n        return `calc((0px + ${previousInset}) + (${previousWidth} / 2) + ${adjoiningMargin} + (${width} / 2))`;\n    }\n\n    #resolveLength(\n        value\n    ) {\n        const measure =\n            document.createElement(\n                "div"\n            );\n\n        measure.style.position =\n            "absolute";\n\n        measure.style.visibility =\n            "hidden";\n\n        measure.style.pointerEvents =\n            "none";\n\n        measure.style.width =\n            value;\n\n        measure.style.height =\n            "0";\n\n        this.#shadowRoot.appendChild(\n            measure\n        );\n\n        const pixels =\n            measure.getBoundingClientRect()\n                .width;\n\n        measure.remove();\n\n        return Number.isFinite(\n            pixels\n        )\n            ? pixels\n            : 0;\n    }\n\n    #updateContour() {\n        const parent =\n            this.parentElement;\n\n        if (\n            !parent ||\n            parent.localName !==\n                "ring-container" ||\n            !this.#contourLayer\n        ) {\n            return;\n        }\n\n        const width =\n            parent.clientWidth;\n\n        const height =\n            parent.clientHeight;\n\n        if (\n            width <= 0 ||\n            height <= 0\n        ) {\n            this.#contourLayer.style.backgroundImage =\n                "none";\n\n            return;\n        }\n\n        const ringWidth =\n            this.#resolveLength(\n                parent.getAttribute(\n                    "width"\n                ) ??\n                "0px"\n            );\n\n        const ringInset =\n            this.#resolveLength(\n                this.#getEffectiveRingInset(\n                    parent\n                )\n            );\n\n        const radius =\n            Math.min(\n                width,\n                height\n            ) / 2;\n\n        const innerRadius =\n            Math.max(\n                0,\n                radius -\n                    ringInset -\n                    ringWidth / 2\n            );\n\n        const centerRadius =\n            Math.max(\n                0,\n                radius -\n                    ringInset\n            );\n\n        const outerRadius =\n            Math.max(\n                0,\n                radius -\n                    ringInset +\n                    ringWidth / 2\n            );\n\n        this.#contourLayer.style.backgroundImage =\n            `radial-gradient(circle at center, ` +\n            `rgba(0, 0, 0, 0.28) ${innerRadius}px, ` +\n            `rgba(255, 255, 255, 0.34) ${centerRadius}px, ` +\n            `rgba(0, 0, 0, 0.22) ${outerRadius}px)`;\n    }\n\n    #updateClipPath() {\n        const parent =\n            this.parentElement;'''

if marker not in text:
    raise SystemExit('updateClipPath marker not found')
text = text.replace(marker, helpers, 1)

old2 = '''        if (\n            !parent\n        ) {\n            return;\n        }\n\n        const width ='''
new2 = '''        if (\n            !parent\n        ) {\n            return;\n        }\n\n        this.#updateContour();\n\n        const width ='''
if old2 not in text:
    raise SystemExit('parent guard not found')
text = text.replace(old2, new2, 1)

path.write_text(text)
